```csharp
public class ClickMimicry
{
    public async Task ClickHumanLikeAsync(IPage page, ILocator element)
    {
        var box = await element.BoundingBoxAsync();
        if (box == null) throw new Exception("Element not visible");

        // Random point within element (not always center)
        var offsetX = _random.Next(5, (int)box.Width - 5);
        var offsetY = _random.Next(5, (int)box.Height - 5);

        var clickX = box.X + offsetX;
        var clickY = box.Y + offsetY;

        // Move mouse to element
        await _mouseMimicry.MoveMouseHumanLikeAsync(page, clickX, clickY);

        // Small pause before click
        await _timing.PreClickDelayAsync();

        // Click
        await page.Mouse.ClickAsync(clickX, clickY);

        // Pause after click
        await _timing.PostClickDelayAsync();
    }
}
