```csharp
public sealed class SpiderContractConfiguration
{
    public bool Enabled { get; set; } = true;
    public List<string> TestUrls { get; set; } = new();
    public List<string> ExpectedFields { get; set; } = new();
    public Dictionary<string, ValidationRule> ValidationRules { get; set; } = new();
    public bool CacheResponses { get; set; } = true;
    public string? CacheDirectory { get; set; }
    public TimeSpan? CacheTtl { get; set; } = TimeSpan.FromHours(24);
    public bool FailOnMissingContracts { get; set; } = false;
    public int MaxConcurrentContracts { get; set; } = 5;
    public TimeSpan ContractTimeout { get; set; } = TimeSpan.FromSeconds(30);
    public bool SkipNetworkContracts { get; set; } = false;  // Use only cached responses
    public LogLevel FailureLogLevel { get; set; } = LogLevel.Error;
}

public enum ContractType
{
    ItemContract,      // Validates items returned by spider
    RequestContract,   // Validates requests yielded by spider
    ErrorContract      // Validates error handling behavior
}

[AttributeUsage(AttributeTargets.Method, AllowMultiple = true)]
public sealed class SpiderContractAttribute : Attribute
{
    public required string Url { get; set; }
    public ContractType Type { get; set; } = ContractType.ItemContract;
    public Type? ItemType { get; set; }
    public int MinItems { get; set; } = 1;
    public int? MaxItems { get; set; }
    public string[] RequiredFields { get; set; } = Array.Empty<string>();
    public Type? ValidatorType { get; set; }
}

public interface IContractValidator
{
    Task<ValidationResult> ValidateAsync(Item item, CancellationToken ct = default);
}

public sealed class ContractResult
{
    public string SpiderName { get; set; } = string.Empty;
    public string MethodName { get; set; } = string.Empty;
    public string Url { get; set; } = string.Empty;
    public bool Passed { get; set; }
    public TimeSpan ExecutionTime { get; set; }
    public List<ContractViolation> Violations { get; set; } = new();
    public List<Item> ExtractedItems { get; set; } = new();
}

public sealed class ContractViolation
{
    public string FieldName { get; set; } = string.Empty;
    public string Expected { get; set; } = string.Empty;
    public string Actual { get; set; } = string.Empty;
    public string Message { get; set; } = string.Empty;
    public ViolationType Type { get; set; }
}
